#!/usr/bin/env bun

import { readFileSync } from 'fs';

// Let's analyze the structure of different resource types to understand the schema
const filename = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir/Kerry175_Walker122_7fd1151f-a5eb-f3ca-edbc-b6e49f37f4eb.json';

function analyzeResourceStructure() {
  console.log('🔍 Analyzing resource structure for schema creation...\n');

  const content = readFileSync(filename, 'utf8');
  const data = JSON.parse(content);

  // Function to get unique keys from objects
  function getUniqueKeys(obj: any, prefix = ''): Set<string> {
    const keys = new Set<string>();

    if (Array.isArray(obj)) {
      obj.forEach(item => {
        getUniqueKeys(item, prefix).forEach(key => keys.add(key));
      });
    } else if (obj && typeof obj === 'object') {
      Object.keys(obj).forEach(key => {
        const fullKey = prefix ? `${prefix}.${key}` : key;
        keys.add(fullKey);

        if (typeof obj[key] === 'object' && obj[key] !== null) {
          getUniqueKeys(obj[key], fullKey).forEach(subKey => keys.add(subKey));
        }
      });
    }

    return keys;
  }

  // Analyze each resource type
  const resourceAnalysis: Record<string, {
    count: number;
    keys: Set<string>;
    examples: any[];
  }> = {};

  for (const entry of data.entry) {
    const resourceType = entry.resource?.resourceType;
    if (!resourceType) continue;

    if (!resourceAnalysis[resourceType]) {
      resourceAnalysis[resourceType] = {
        count: 0,
        keys: new Set(),
        examples: []
      };
    }

    resourceAnalysis[resourceType].count++;
    getUniqueKeys(entry.resource).forEach(key => 
      resourceAnalysis[resourceType].keys.add(key)
    );

    // Store first few examples
    if (resourceAnalysis[resourceType].examples.length < 3) {
      resourceAnalysis[resourceType].examples.push(entry.resource);
    }
  }

  // Print analysis
  console.log('📊 Resource Type Analysis:\n');

  for (const [resourceType, analysis] of Object.entries(resourceAnalysis)) {
    console.log(`🏥 ${resourceType} (${analysis.count} instances)`);
    console.log('   Keys:', Array.from(analysis.keys).sort().join(', '));

    // Show example structure for key types
    if (['Patient', 'Observation', 'Condition', 'Procedure', 'Encounter'].includes(resourceType)) {
      console.log('   Example structure:');
      console.log('   ', JSON.stringify(analysis.examples[0], null, 2).split('\n').slice(0, 20).join('\n   '));
    }
    console.log('');
  }

  // Analyze common patterns
  console.log('🔍 Common Pattern Analysis:\n');

  // Check for coding patterns
  const codingExamples = [];
  for (const entry of data.entry) {
    if (entry.resource?.code?.coding) {
      codingExamples.push(entry.resource.code.coding[0]);
      if (codingExamples.length >= 10) break;
    }
  }

  if (codingExamples.length > 0) {
    console.log('📝 Coding Pattern Examples:');
    codingExamples.forEach((coding, i) => {
      console.log(`   ${i + 1}. ${JSON.stringify(coding)}`);
    });
    console.log('');
  }

  // Check for reference patterns
  const referenceExamples = [];
  for (const entry of data.entry) {
    if (entry.resource?.subject?.reference) {
      referenceExamples.push(entry.resource.subject.reference);
      if (referenceExamples.length >= 10) break;
    }
  }

  if (referenceExamples.length > 0) {
    console.log('🔗 Reference Pattern Examples:');
    referenceExamples.forEach((ref, i) => {
      console.log(`   ${i + 1}. ${ref}`);
    });
    console.log('');
  }

  // Check for identifier patterns
  const identifierExamples = [];
  for (const entry of data.entry) {
    if (entry.resource?.identifier) {
      identifierExamples.push(entry.resource.identifier[0]);
      if (identifierExamples.length >= 5) break;
    }
  }

  if (identifierExamples.length > 0) {
    console.log('🆔 Identifier Pattern Examples:');
    identifierExamples.forEach((id, i) => {
      console.log(`   ${i + 1}. ${JSON.stringify(id)}`);
    });
    console.log('');
  }

  console.log('✅ Schema structure analysis complete!');
}

if (import.meta.main) {
  analyzeResourceStructure();
}

