#!/usr/bin/env bun

import { readFileSync } from 'fs';

// Let's focus on the most important resource types for schema creation
const filename = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir/Kerry175_Walker122_7fd1151f-a5eb-f3ca-edbc-b6e49f37f4eb.json';

function focusedSchemaAnalysis() {
  console.log('🎯 Focused analysis for schema creation...\n');

  const content = readFileSync(filename, 'utf8');
  const data = JSON.parse(content);

  // Focus on these key resource types
  const keyResourceTypes = ['Patient', 'Observation', 'Condition', 'Encounter', 'Procedure'];

  for (const resourceType of keyResourceTypes) {
    console.log(`\n📋 ${resourceType} Resource Analysis:`);
    console.log('=' .repeat(50));

    const resources = data.entry.filter((entry: any) => entry.resource?.resourceType === resourceType);

    if (resources.length === 0) {
      console.log('❌ No resources found of this type');
      continue;
    }

    console.log(`Found ${resources.length} ${resourceType} resources`);

    // Show first example in detail
    const example = resources[0].resource;
    console.log('\n📝 Example Structure:');
    console.log(JSON.stringify(example, null, 2));

    // Analyze optional vs required fields
    const allFields = new Set<string>();
    const fieldCounts = new Map<string, number>();

    for (const resource of resources) {
      const flattenObject = (obj: any, prefix = '') => {
        for (const key in obj) {
          if (obj.hasOwnProperty(key)) {
            const fullKey = prefix ? `${prefix}.${key}` : key;
            allFields.add(fullKey);
            fieldCounts.set(fullKey, (fieldCounts.get(fullKey) || 0) + 1);
          }
        }
      };

      flattenObject(resource.resource);
    }

    console.log('\n🔍 Field Analysis:');
    const sortedFields = Array.from(allFields).sort();
    for (const field of sortedFields) {
      const count = fieldCounts.get(field) || 0;
      const isRequired = count === resources.length;
      console.log(`   ${field}: ${count}/${resources.length} ${isRequired ? '(REQUIRED)' : '(optional)'}`);
    }

    console.log('\n' + '='.repeat(50));
  }

  // Look at common patterns
  console.log('\n🧩 Common FHIR Patterns:');
  console.log('=' .repeat(50));

  // Coding pattern
  const codingExample = data.entry.find((entry: any) => entry.resource?.code?.coding);
  if (codingExample) {
    console.log('\n📝 Coding Pattern:');
    console.log(JSON.stringify(codingExample.resource.code.coding[0], null, 2));
  }

  // Reference pattern
  const referenceExample = data.entry.find((entry: any) => entry.resource?.subject?.reference);
  if (referenceExample) {
    console.log('\n🔗 Reference Pattern:');
    console.log(JSON.stringify(referenceExample.resource.subject, null, 2));
  }

  // Identifier pattern
  const identifierExample = data.entry.find((entry: any) => entry.resource?.identifier);
  if (identifierExample) {
    console.log('\n🆔 Identifier Pattern:');
    console.log(JSON.stringify(identifierExample.resource.identifier[0], null, 2));
  }

  // Extension pattern
  const extensionExample = data.entry.find((entry: any) => entry.resource?.extension);
  if (extensionExample) {
    console.log('\n🔧 Extension Pattern:');
    console.log(JSON.stringify(extensionExample.resource.extension[0], null, 2));
  }
}

if (import.meta.main) {
  focusedSchemaAnalysis();
}

