import { readFileSync } from 'fs';
import { 
  BundleSchema, 
  BundleValidationSchema, 
  type Bundle, 
  getBundleResources, 
  getPatient, 
  getObservations, 
  getConditions, 
  getProcedures, 
  getEncounters 
} from '../schema/fhir-bundle';
import { type Patient } from '../schema/fhir-patient';
import { type Observation, type Condition, type Procedure } from '../schema/fhir-clinical';
import { type Encounter } from '../schema/fhir-administrative';
import { ZodError } from 'zod';

/**
 * Enhanced FHIR Bundle Loader with advanced features
 * 
 * Features:
 * - Streaming validation for large files
 * - Resource-specific extraction and transformation
 * - Performance monitoring and optimization
 * - Comprehensive metadata collection
 * - Error recovery and partial loading
 * - Type-safe resource accessors
 */

export interface EnhancedLoadOptions {
  strict?: boolean;
  maxObservations?: number;
  includeUnknownResources?: boolean;
  validateReferences?: boolean;
  collectMetrics?: boolean;
  timeoutMs?: number;
}

export interface LoadMetrics {
  loadTime: number;
  validationTime: number;
  resourceProcessingTime: number;
  memoryUsage: number;
  resourceCounts: Record<string, number>;
  observationTypes: Record<string, number>;
  conditionTypes: Record<string, number>;
  dateRange: { earliest: string; latest: string } | null;
  performanceWarnings: string[];
}

export interface ProcessedBundle {
  bundle: Bundle;
  patient: Patient;
  observations: Observation[];
  conditions: Condition[];
  procedures: Procedure[];
  encounters: Encounter[];
  otherResources: any[];
  metrics: LoadMetrics;
}

export interface EnhancedLoadResult {
  success: boolean;
  processedBundle?: ProcessedBundle;
  errors?: string[];
  warnings?: string[];
  partialResults?: {
    validResourceCount: number;
    invalidResourceCount: number;
    bundle?: Bundle;
  };
}

export class EnhancedFhirBundleLoader {
  private options: Required<EnhancedLoadOptions>;

  constructor(options: EnhancedLoadOptions = {}) {
    this.options = {
      strict: options.strict ?? false,
      maxObservations: options.maxObservations ?? 10000,
      includeUnknownResources: options.includeUnknownResources ?? true,
      validateReferences: options.validateReferences ?? true,
      collectMetrics: options.collectMetrics ?? true,
      timeoutMs: options.timeoutMs ?? 30000
    };
  }

  /**
   * Load and process a FHIR Bundle from a file
   */
  async loadFromFile(filePath: string): Promise<EnhancedLoadResult> {
    const startTime = Date.now();

    try {
      // Read file with timeout
      const fileContent = await this.readFileWithTimeout(filePath);

      // Parse JSON
      let jsonData: any;
      try {
        jsonData = JSON.parse(fileContent);
      } catch (parseError) {
        return {
          success: false,
          errors: [`JSON parsing failed: ${parseError instanceof Error ? parseError.message : String(parseError)}`]
        };
      }

      return this.processBundle(jsonData, filePath, startTime);
    } catch (error) {
      return {
        success: false,
        errors: [`File loading failed: ${error instanceof Error ? error.message : String(error)}`]
      };
    }
  }

  /**
   * Load and process a FHIR Bundle from JSON data
   */
  async loadFromJson(jsonData: any): Promise<EnhancedLoadResult> {
    const startTime = Date.now();
    return this.processBundle(jsonData, '<json-data>', startTime);
  }

  /**
   * Process a FHIR Bundle with comprehensive validation and extraction
   */
  private async processBundle(jsonData: any, source: string, startTime: number): Promise<EnhancedLoadResult> {
    const errors: string[] = [];
    const warnings: string[] = [];

    // Initialize metrics
    const metrics: LoadMetrics = {
      loadTime: 0,
      validationTime: 0,
      resourceProcessingTime: 0,
      memoryUsage: 0,
      resourceCounts: {},
      observationTypes: {},
      conditionTypes: {},
      dateRange: null,
      performanceWarnings: []
    };

    // Validate bundle structure
    const validationStartTime = Date.now();
    let bundle: Bundle;

    try {
      const schema = this.options.strict ? BundleValidationSchema : BundleSchema;
      bundle = schema.parse(jsonData);
    } catch (error) {
      if (error instanceof ZodError) {
        return {
          success: false,
          errors: [
            'Bundle validation failed:',
            ...error.errors.map(err => `  ${err.path.join('.')}: ${err.message}`)
          ]
        };
      }

      return {
        success: false,
        errors: [`Bundle validation failed: ${error instanceof Error ? error.message : String(error)}`]
      };
    }

    metrics.validationTime = Date.now() - validationStartTime;

    // Process resources
    const processingStartTime = Date.now();
    const processedResult = await this.processResources(bundle, warnings, metrics);
    metrics.resourceProcessingTime = Date.now() - processingStartTime;

    // Calculate total time
    metrics.loadTime = Date.now() - startTime;

    // Collect memory usage if available
    if (typeof process !== 'undefined' && process.memoryUsage) {
      metrics.memoryUsage = process.memoryUsage().heapUsed;
    }

    // Performance warnings
    if (metrics.loadTime > 1000) {
      metrics.performanceWarnings.push(`Load time ${metrics.loadTime}ms exceeds 1s threshold`);
    }

    if (processedResult.observations.length > this.options.maxObservations) {
      metrics.performanceWarnings.push(`Observation count ${processedResult.observations.length} exceeds maximum ${this.options.maxObservations}`);
    }

    // Reference validation
    if (this.options.validateReferences) {
      const referenceWarnings = this.validateReferences(processedResult);
      warnings.push(...referenceWarnings);
    }

    // Generate additional warnings
    this.generateWarnings(processedResult, warnings, metrics);

    return {
      success: true,
      processedBundle: {
        ...processedResult,
        metrics
      },
      errors: errors.length > 0 ? errors : undefined,
      warnings: warnings.length > 0 ? warnings : undefined
    };
  }

  /**
   * Process and extract resources from bundle
   */
  private async processResources(bundle: Bundle, warnings: string[], metrics: LoadMetrics): Promise<{
    bundle: Bundle;
    patient: Patient;
    observations: Observation[];
    conditions: Condition[];
    procedures: Procedure[];
    encounters: Encounter[];
    otherResources: any[];
  }> {
    const resources = getBundleResources(bundle);
    const dates: string[] = [];

    // Count resource types
    for (const resource of resources) {
      metrics.resourceCounts[resource.resourceType] = (metrics.resourceCounts[resource.resourceType] || 0) + 1;
    }

    // Extract patient
    const patient = getPatient(bundle);
    if (!patient) {
      throw new Error('No Patient resource found in bundle');
    }

    // Extract observations
    const observations = getObservations(bundle);

    // Collect observation types and dates
    for (const observation of observations) {
      if (observation.code?.coding?.[0]?.display) {
        const display = observation.code.coding[0].display;
        metrics.observationTypes[display] = (metrics.observationTypes[display] || 0) + 1;
      }

      if (observation.effectiveDateTime) {
        dates.push(observation.effectiveDateTime);
      }
    }

    // Extract conditions
    const conditions = getConditions(bundle);

    // Collect condition types
    for (const condition of conditions) {
      if (condition.code?.coding?.[0]?.display) {
        const display = condition.code.coding[0].display;
        metrics.conditionTypes[display] = (metrics.conditionTypes[display] || 0) + 1;
      }

      if (condition.onsetDateTime) {
        dates.push(condition.onsetDateTime);
      }
    }

    // Extract procedures
    const procedures = getProcedures(bundle);

    // Collect procedure dates
    for (const procedure of procedures) {
      if (procedure.performedPeriod?.start) {
        dates.push(procedure.performedPeriod.start);
      }
    }

    // Extract encounters
    const encounters = getEncounters(bundle);

    // Collect encounter dates
    for (const encounter of encounters) {
      if (encounter.period?.start) {
        dates.push(encounter.period.start);
      }
    }

    // Extract other resources
    const knownTypes = new Set(['Patient', 'Observation', 'Condition', 'Procedure', 'Encounter']);
    const otherResources = this.options.includeUnknownResources 
      ? resources.filter(r => !knownTypes.has(r.resourceType))
      : [];

    // Calculate date range
    if (dates.length > 0) {
      const sortedDates = dates.sort();
      metrics.dateRange = {
        earliest: sortedDates[0],
        latest: sortedDates[sortedDates.length - 1]
      };
    }

    return {
      bundle,
      patient,
      observations,
      conditions,
      procedures,
      encounters,
      otherResources
    };
  }

  /**
   * Validate resource references
   */
  private validateReferences(processedResult: any): string[] {
    const warnings: string[] = [];
    const resourceIds = new Set<string>();

    // Collect all resource IDs
    const allResources = [
      processedResult.patient,
      ...processedResult.observations,
      ...processedResult.conditions,
      ...processedResult.procedures,
      ...processedResult.encounters,
      ...processedResult.otherResources
    ];

    for (const resource of allResources) {
      if (resource?.id) {
        resourceIds.add(resource.id);
      }
    }

    // Check references in observations
    for (const observation of processedResult.observations) {
      if (observation.subject?.reference) {
        const referencedId = observation.subject.reference.replace('urn:uuid:', '');
        if (!resourceIds.has(referencedId)) {
          warnings.push(`Observation ${observation.id} references unknown resource ${referencedId}`);
        }
      }
    }

    // Check references in conditions
    for (const condition of processedResult.conditions) {
      if (condition.subject?.reference) {
        const referencedId = condition.subject.reference.replace('urn:uuid:', '');
        if (!resourceIds.has(referencedId)) {
          warnings.push(`Condition ${condition.id} references unknown resource ${referencedId}`);
        }
      }
    }

    return warnings;
  }

  /**
   * Generate comprehensive warnings
   */
  private generateWarnings(processedResult: any, warnings: string[], metrics: LoadMetrics): void {
    // Performance warnings
    if (metrics.performanceWarnings.length > 0) {
      warnings.push(...metrics.performanceWarnings);
    }

    // Data quality warnings
    if (processedResult.observations.length === 0) {
      warnings.push('No observations found - unusual for a complete patient record');
    }

    if (processedResult.conditions.length === 0) {
      warnings.push('No conditions found - unusual for a complete patient record');
    }

    // Date range warnings
    if (metrics.dateRange) {
      const startYear = new Date(metrics.dateRange.earliest).getFullYear();
      const endYear = new Date(metrics.dateRange.latest).getFullYear();
      const yearSpan = endYear - startYear;

      if (yearSpan > 100) {
        warnings.push(`Date range spans ${yearSpan} years - verify data quality`);
      }
    }

    // Resource distribution warnings
    const observationCount = metrics.resourceCounts['Observation'] || 0;
    const totalResources = Object.values(metrics.resourceCounts).reduce((sum, count) => sum + count, 0);

    if (observationCount > totalResources * 0.8) {
      warnings.push('Observations comprise >80% of resources - may indicate data quality issues');
    }
  }

  /**
   * Read file with timeout
   */
  private async readFileWithTimeout(filePath: string): Promise<string> {
    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        reject(new Error(`File read timeout after ${this.options.timeoutMs}ms`));
      }, this.options.timeoutMs);

      try {
        const content = readFileSync(filePath, 'utf8');
        clearTimeout(timeout);
        resolve(content);
      } catch (error) {
        clearTimeout(timeout);
        reject(error);
      }
    });
  }

  /**
   * Get summary statistics for multiple files
   */
  async processBatch(filePaths: string[]): Promise<{
    totalFiles: number;
    successCount: number;
    failureCount: number;
    aggregatedMetrics: {
      totalResourceCount: number;
      averageLoadTime: number;
      resourceTypeDistribution: Record<string, number>;
      commonObservationTypes: Array<{ type: string; count: number }>;
      commonConditionTypes: Array<{ type: string; count: number }>;
    };
    results: Array<{ filePath: string; result: EnhancedLoadResult }>;
  }> {
    const results: Array<{ filePath: string; result: EnhancedLoadResult }> = [];
    const aggregatedMetrics = {
      totalResourceCount: 0,
      averageLoadTime: 0,
      resourceTypeDistribution: {} as Record<string, number>,
      commonObservationTypes: {} as Record<string, number>,
      commonConditionTypes: {} as Record<string, number>
    };

    // Process files
    for (const filePath of filePaths) {
      const result = await this.loadFromFile(filePath);
      results.push({ filePath, result });

      // Aggregate metrics
      if (result.success && result.processedBundle) {
        const metrics = result.processedBundle.metrics;
        aggregatedMetrics.totalResourceCount += Object.values(metrics.resourceCounts).reduce((sum, count) => sum + count, 0);

        // Aggregate resource types
        for (const [type, count] of Object.entries(metrics.resourceCounts)) {
          aggregatedMetrics.resourceTypeDistribution[type] = (aggregatedMetrics.resourceTypeDistribution[type] || 0) + count;
        }

        // Aggregate observation types
        for (const [type, count] of Object.entries(metrics.observationTypes)) {
          aggregatedMetrics.commonObservationTypes[type] = (aggregatedMetrics.commonObservationTypes[type] || 0) + count;
        }

        // Aggregate condition types
        for (const [type, count] of Object.entries(metrics.conditionTypes)) {
          aggregatedMetrics.commonConditionTypes[type] = (aggregatedMetrics.commonConditionTypes[type] || 0) + count;
        }
      }
    }

    // Calculate averages
    const successCount = results.filter(r => r.result.success).length;
    const totalLoadTime = results
      .filter(r => r.result.success && r.result.processedBundle)
      .reduce((sum, r) => sum + r.result.processedBundle!.metrics.loadTime, 0);

    aggregatedMetrics.averageLoadTime = successCount > 0 ? totalLoadTime / successCount : 0;

    // Sort top observation and condition types
    const sortedObservationTypes = Object.entries(aggregatedMetrics.commonObservationTypes)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 20)
      .map(([type, count]) => ({ type, count }));

    const sortedConditionTypes = Object.entries(aggregatedMetrics.commonConditionTypes)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 20)
      .map(([type, count]) => ({ type, count }));

    return {
      totalFiles: filePaths.length,
      successCount,
      failureCount: filePaths.length - successCount,
      aggregatedMetrics: {
        ...aggregatedMetrics,
        commonObservationTypes: sortedObservationTypes,
        commonConditionTypes: sortedConditionTypes
      },
      results
    };
  }
}

// Export convenience functions
export const loadFhirBundleEnhanced = async (filePath: string, options?: EnhancedLoadOptions): Promise<EnhancedLoadResult> => {
  const loader = new EnhancedFhirBundleLoader(options);
  return loader.loadFromFile(filePath);
};

export const processFhirBatch = async (filePaths: string[], options?: EnhancedLoadOptions) => {
  const loader = new EnhancedFhirBundleLoader(options);
  return loader.processBatch(filePaths);
};

#!/usr/bin/env bun

import { readdirSync, statSync } from 'fs';
import { join } from 'path';
import { EnhancedFhirBundleLoader } from '../loaders/enhanced-fhir-loader';
import { isPatient, isObservation, isCondition } from '../schema/fhir-bundle';

/**
 * Comprehensive Example: Using FHIR Schemas and Loaders
 * 
 * This example demonstrates:
 * 1. How to use the enhanced FHIR loader
 * 2. Type-safe resource extraction
 * 3. Data analysis with validated schemas
 * 4. Performance monitoring
 * 5. Error handling and validation
 */

const DATA_DIR = '/Users/hrishioa/Dropbox/Projects/Southbridge/experiments/sealed-agents/tests/healthcare-ehr-langton/data/fhir';

interface PatientAnalysis {
  patientId: string;
  demographics: {
    name: string;
    gender: string;
    birthDate: string;
    age: number;
  };
  medicalComplexity: {
    conditionCount: number;
    observationCount: number;
    procedureCount: number;
    encounterCount: number;
    chronictypes: string[];
    riskScore: number;
  };
  timespan: {
    earliest: string;
    latest: string;
    yearSpan: number;
  };
  qualityMetrics: {
    hasVitalSigns: boolean;
    hasLabResults: boolean;
    hasChronicConditions: boolean;
    completenessScore: number;
  };
}

async function main() {
  console.log('🏥 FHIR Schema Usage Example\n');

  // Get sample files for analysis
  const files = readdirSync(DATA_DIR).filter(f => f.endsWith('.json'));

  // Select a diverse sample
  const sampleFiles = [
    // Small file
    files.find(f => statSync(join(DATA_DIR, f)).size < 5 * 1024 * 1024),
    // Medium file
    files.find(f => {
      const size = statSync(join(DATA_DIR, f)).size;
      return size >= 10 * 1024 * 1024 && size < 30 * 1024 * 1024;
    }),
    // Large file
    files.find(f => statSync(join(DATA_DIR, f)).size >= 30 * 1024 * 1024)
  ].filter(Boolean).slice(0, 3);

  console.log(`📊 Analyzing ${sampleFiles.length} patient files...\n`);

  // Initialize enhanced loader with custom options
  const loader = new EnhancedFhirBundleLoader({
    strict: true,
    maxObservations: 5000,
    validateReferences: true,
    collectMetrics: true,
    timeoutMs: 30000
  });

  const patientAnalyses: PatientAnalysis[] = [];

  // Process each file
  for (const filename of sampleFiles) {
    const filePath = join(DATA_DIR, filename);
    console.log(`🔍 Processing ${filename}...`);

    try {
      const result = await loader.loadFromFile(filePath);

      if (result.success && result.processedBundle) {
        const analysis = analyzePatient(result.processedBundle);
        patientAnalyses.push(analysis);

        console.log(`   ✅ Success - ${analysis.demographics.name}`);
        console.log(`   📊 Resources: ${analysis.medicalComplexity.observationCount} obs, ${analysis.medicalComplexity.conditionCount} conditions`);
        console.log(`   🏥 Risk Score: ${analysis.medicalComplexity.riskScore}/10`);
        console.log(`   📅 Timespan: ${analysis.timespan.yearSpan} years`);
        console.log(`   ⭐ Quality: ${analysis.qualityMetrics.completenessScore}/10`);
      } else {
        console.log(`   ❌ Failed to process ${filename}`);
        if (result.errors) {
          for (const error of result.errors.slice(0, 3)) {
            console.log(`      💥 ${error}`);
          }
        }
      }
    } catch (error) {
      console.log(`   💥 Exception: ${error instanceof Error ? error.message : String(error)}`);
    }

    console.log('');
  }

  // Aggregate analysis
  if (patientAnalyses.length > 0) {
    console.log('📈 AGGREGATE ANALYSIS:');
    console.log('=' .repeat(50));

    const avgAge = patientAnalyses.reduce((sum, p) => sum + p.demographics.age, 0) / patientAnalyses.length;
    const avgConditions = patientAnalyses.reduce((sum, p) => sum + p.medicalComplexity.conditionCount, 0) / patientAnalyses.length;
    const avgObservations = patientAnalyses.reduce((sum, p) => sum + p.medicalComplexity.observationCount, 0) / patientAnalyses.length;
    const avgRiskScore = patientAnalyses.reduce((sum, p) => sum + p.medicalComplexity.riskScore, 0) / patientAnalyses.length;
    const avgQualityScore = patientAnalyses.reduce((sum, p) => sum + p.qualityMetrics.completenessScore, 0) / patientAnalyses.length;

    console.log(`Average age: ${avgAge.toFixed(1)} years`);
    console.log(`Average conditions: ${avgConditions.toFixed(1)}`);
    console.log(`Average observations: ${avgObservations.toFixed(0)}`);
    console.log(`Average risk score: ${avgRiskScore.toFixed(1)}/10`);
    console.log(`Average quality score: ${avgQualityScore.toFixed(1)}/10`);

    // Gender distribution
    const genderCounts = patientAnalyses.reduce((acc, p) => {
      acc[p.demographics.gender] = (acc[p.demographics.gender] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);

    console.log('\n👥 Gender Distribution:');
    for (const [gender, count] of Object.entries(genderCounts)) {
      console.log(`  ${gender}: ${count}`);
    }

    // Common chronic conditions
    const allChronicConditions = patientAnalyses.flatMap(p => p.medicalComplexity.chronictypes);
    const conditionCounts = allChronicConditions.reduce((acc, condition) => {
      acc[condition] = (acc[condition] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);

    console.log('\n🏥 Common Chronic Conditions:');
    Object.entries(conditionCounts)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 10)
      .forEach(([condition, count]) => {
        console.log(`  ${condition}: ${count}`);
      });
  }

  // Demonstrate type safety
  console.log('\n🔒 TYPE SAFETY DEMONSTRATION:');
  console.log('=' .repeat(50));

  if (patientAnalyses.length > 0) {
    const firstAnalysis = patientAnalyses[0];

    // This would cause a TypeScript error if demographics didn't have these properties
    console.log(`Patient name: ${firstAnalysis.demographics.name}`);
    console.log(`Birth date: ${firstAnalysis.demographics.birthDate}`);
    console.log(`Age: ${firstAnalysis.demographics.age}`);

    // Demonstrate safe resource type checking
    console.log('\n🔍 Resource Type Safety:');
    const filename = sampleFiles[0];
    const result = await loader.loadFromFile(join(DATA_DIR, filename));

    if (result.success && result.processedBundle) {
      const resources = [
        result.processedBundle.patient,
        ...result.processedBundle.observations.slice(0, 2),
        ...result.processedBundle.conditions.slice(0, 2)
      ];

      for (const resource of resources) {
        if (isPatient(resource)) {
          console.log(`  Patient: ${resource.name?.[0]?.given?.[0]} ${resource.name?.[0]?.family}`);
        } else if (isObservation(resource)) {
          console.log(`  Observation: ${resource.code?.coding?.[0]?.display || 'Unknown'}`);
        } else if (isCondition(resource)) {
          console.log(`  Condition: ${resource.code?.coding?.[0]?.display || 'Unknown'}`);
        }
      }
    }
  }

  console.log('\n✅ Schema usage example complete!');
}

/**
 * Analyze a patient bundle to extract meaningful insights
 */
function analyzePatient(processedBundle: any): PatientAnalysis {
  const { patient, observations, conditions, procedures, encounters, metrics } = processedBundle;

  // Calculate age
  const birthDate = new Date(patient.birthDate);
  const age = new Date().getFullYear() - birthDate.getFullYear();

  // Identify chronic conditions
  const chronicConditionKeywords = ['diabetes', 'hypertension', 'heart disease', 'kidney disease', 'copd', 'cancer'];
  const chronicConditions = conditions.filter((condition: any) => 
    chronicConditionKeywords.some(keyword => 
      condition.code?.coding?.[0]?.display?.toLowerCase().includes(keyword)
    )
  );

  // Calculate risk score (0-10) based on various factors
  let riskScore = 0;
  riskScore += Math.min(age / 80 * 3, 3); // Age factor (0-3)
  riskScore += Math.min(chronicConditions.length * 0.5, 3); // Chronic condition factor (0-3)
  riskScore += Math.min(conditions.length / 100 * 2, 2); // Total condition factor (0-2)
  riskScore += Math.min(observations.length / 5000 * 2, 2); // Observation frequency factor (0-2)

  // Quality metrics
  const hasVitalSigns = observations.some((obs: any) => 
    obs.code?.coding?.[0]?.display?.toLowerCase().includes('blood pressure') ||
    obs.code?.coding?.[0]?.display?.toLowerCase().includes('heart rate') ||
    obs.code?.coding?.[0]?.display?.toLowerCase().includes('temperature')
  );

  const hasLabResults = observations.some((obs: any) => 
    obs.code?.coding?.[0]?.display?.toLowerCase().includes('glucose') ||
    obs.code?.coding?.[0]?.display?.toLowerCase().includes('cholesterol') ||
    obs.code?.coding?.[0]?.display?.toLowerCase().includes('hemoglobin')
  );

  const hasChronicConditions = chronicConditions.length > 0;

  // Completeness score (0-10)
  let completenessScore = 0;
  completenessScore += patient.name ? 2 : 0;
  completenessScore += patient.birthDate ? 2 : 0;
  completenessScore += hasVitalSigns ? 2 : 0;
  completenessScore += hasLabResults ? 2 : 0;
  completenessScore += conditions.length > 0 ? 1 : 0;
  completenessScore += procedures.length > 0 ? 1 : 0;

  // Calculate timespan
  const dates = [
    ...observations.map((obs: any) => obs.effectiveDateTime).filter(Boolean),
    ...conditions.map((cond: any) => cond.onsetDateTime).filter(Boolean),
    ...procedures.map((proc: any) => proc.performedPeriod?.start).filter(Boolean)
  ];

  const sortedDates = dates.sort();
  const earliest = sortedDates[0] || patient.birthDate;
  const latest = sortedDates[sortedDates.length - 1] || new Date().toISOString();
  const yearSpan = new Date(latest).getFullYear() - new Date(earliest).getFullYear();

  return {
    patientId: patient.id,
    demographics: {
      name: `${patient.name?.[0]?.given?.[0]} ${patient.name?.[0]?.family}`,
      gender: patient.gender,
      birthDate: patient.birthDate,
      age
    },
    medicalComplexity: {
      conditionCount: conditions.length,
      observationCount: observations.length,
      procedureCount: procedures.length,
      encounterCount: encounters.length,
      chronictypes: chronicConditions.map((c: any) => c.code?.coding?.[0]?.display).filter(Boolean),
      riskScore: Math.round(riskScore * 10) / 10
    },
    timespan: {
      earliest,
      latest,
      yearSpan
    },
    qualityMetrics: {
      hasVitalSigns,
      hasLabResults,
      hasChronicConditions,
      completenessScore
    }
  };
}

